const response = $input.first().json;
const companies = response.results || [];
if (companies.length === 0) return [];
return companies.map(c => ({ json: c }));

const crypto = require('crypto');
const company = $json;
const hubspotId = String(company.id);
const props = company.properties || {};
const name = props.name || '';
const existingToken = (props.magic_token || '').trim();
const existingGroup = (props.customer_group || '').trim();
const setCustomerGroup = !existingGroup;

let magicToken;
if (existingToken) {
  magicToken = existingToken;
} else {
  magicToken = crypto.randomUUID();
}

const customerGroupValue = existingGroup || '일반고객';

const airtableBody = {
  records: [{
    fields: {
      'HubSpot 고객 ID': hubspotId,
      '상호': name,
      '매직 토큰': magicToken,
      '고객 그룹': customerGroupValue
    }
  }],
  performUpsert: { fieldsToMergeOn: ['HubSpot 고객 ID'] },
  typecast: true
};

const hubspotProps = { magic_token: magicToken };
if (setCustomerGroup) hubspotProps.customer_group = '일반고객';
const hubspotBody = { properties: hubspotProps };

return {
  json: {
    hubspot_id: hubspotId,
    name,
    magic_token: magicToken,
    customer_group: customerGroupValue,
    set_customer_group: setCustomerGroup,
    token_freshly_generated: !existingToken,
    airtable_body: JSON.stringify(airtableBody),
    hubspot_body: JSON.stringify(hubspotBody)
  }
};
